head.script:
scwin.createWindowTest = function(title) {
    wc1.createWindow(title, "", "", "windowTitle", "windowId", "newWindow", scwin.mainClose);
    //wc1.createWindow( title , iconUrl , src , windowTitle , windowId , openAction , closeAction , windowTooltip )
};
scwin.wc1_onbeforecloseall = function() {
    //debugger;
};
scwin.trigger1_onclick = function(e) {
    wc1.closeOthers("main");
};
scwin.__isCheckVal = function() {
    return WebSquare.wUnit.getDomById($p.id+'wc1_nameLayer_mf_wc1_subWindow3') != null;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_gridView2___autoComplete_0_col1_col1_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheckVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
